    CHECK(!Run(s, v3(0, 0, 0), v3(1, 0, 0), v3(0, 1, 0), 0, __LINE__));
    CHECK(!Run(s, v3(0, 0, 0.5f), v3(1, 1, 0.5f), v3(2, 2, 0.5f), 0, __LINE__));
    CHECK(!Run(s, v3(5, 5, 0.5f), v3(6, 5, 0.5f), v3(5, 6, 0.5f), 0, __LINE__));
