    Sphere s2; s2.Radius = 1.5f; s2.Base = v3(-1.0f, 2.0f, 0.5f);
    CHECK(Run(s2, v3(-1.0f, 2.0f, 1.2f), v3(2.0f, 2.0f, 1.2f), v3(-1.0f, 5.0f, 1.2f), 1, __LINE__));
